import "C"

import (
	"encoding/binary"
	"encoding/json"
	"errors"
	"math"
	"runtime"
	"time"
	"unsafe"
)

var _ = binary.LittleEndian
var _ = runtime.KeepAlive

// db types referenced by Input (the original report package imports db; the
// generated driver needs equivalent definitions to compile).
type dbNode = Node
type Node struct {
	FindingID     int64           `json:"finding_id,omitempty"`
	FindingNodeID int64           `json:"finding_node_id,omitempty"`
	TrafficCount  int             `json:"traffic_count,omitempty"`
	ID            int64           `json:"id"`
	Kind          string          `json:"kind"`
	Payload       json.RawMessage `json:"payload"`
	Priority      int             `json:"priority"`
	State         string          `json:"state"`
	Origin        string          `json:"origin,omitempty"`
	Owner         string          `json:"owner,omitempty"`
	BlockedReason string          `json:"blocked_reason,omitempty"`
	DeleteReason  string          `json:"delete_reason,omitempty"`
	Anchors       []int64         `json:"anchors,omitempty"`
	CreatedAt     time.Time       `json:"created_at"`
	SourceTaskID  int64           `json:"source_task_id,omitempty"`
	Inherited     bool            `json:"inherited,omitempty"`
}

type FindingMeta struct {
	TrafficCount int
	ID           int64
	Status       string
	AssetIDs     []int64
}

type FindingQuality struct {
	FindingMeta
	PoeLevel              int
	VerificationStatus    string
	VerificationNote      string
	Counterevidence       string
	ConfidenceRationale   string
	Report                string
	EvidenceVersion       int64
	ReportEvidenceVersion int64
}

type CoverageEntry struct {
	Surface   string    `json:"surface"`
	RiskArea  string    `json:"risk_area"`
	Outcome   string    `json:"outcome"`
	Evidence  string    `json:"evidence"`
	Reason    string    `json:"reason"`
	Worker    string    `json:"worker,omitempty"`
	IntentID  int64     `json:"intent_id,omitempty"`
	UpdatedAt time.Time `json:"updated_at"`
}

type CoverageGap struct {
	Kind     string `json:"kind"`
	Surface  string `json:"surface,omitempty"`
	RiskArea string `json:"risk_area"`
}

type CoverageCompleteness struct {
	Complete bool   `json:"complete"`
	State    string `json:"state"`
	Caveat   string `json:"caveat"`
}

type CoverageLedger struct {
	Entries         []CoverageEntry       `json:"entries"`
	Gaps            []CoverageGap         `json:"gaps"`
	Unexamined      []string              `json:"unexamined"`
	FindingsByClass map[string]int        `json:"findings_by_class"`
	Completeness    *CoverageCompleteness `json:"completeness"`
}

type Input struct {
	Title       string
	Goal        string
	GeneratedAt time.Time
	AssetCounts map[string]int
	Findings    []*Node
	Coverage    *CoverageLedger // nil when the task's coverage feature is off

	// Quality carries the standalone findings-row data (poe level, verification
	// state, the two attestations, both evidence versions and the reporter-written
	// body) keyed by finding node id, from the report's single quality lookup. The
	// exploration node payload has none of it; without this map every finding would
	// render as an unqualified claim.
	//
	// Three states, deliberately distinct: an empty but non-nil map means the task
	// has no standalone rows (nothing was assessed); a nil map means the lookup
	// failed, which says nothing about the findings themselves; an entry means the
	// row exists. Collapsing failure into absence would turn a database error into a
	// statement about the finding.
	Quality map[int64]FindingQuality
}

// rustAnythingDecode decodes JSON into target; floats may be {"$num": "NaN" | "Infinity" | ...}.
func rustAnythingDecode(raw json.RawMessage, target any) error {
	if f, ok := target.(*float64); ok && len(raw) > 0 && raw[0] == '{' {
		var marker map[string]string
		if err := json.Unmarshal(raw, &marker); err != nil {
			return err
		}
		switch marker["$num"] {
		case "NaN":
			*f = math.NaN()
		case "Infinity":
			*f = math.Inf(1)
		case "-Infinity":
			*f = math.Inf(-1)
		case "-0":
			*f = math.Copysign(0, -1)
		default:
			return errors.New("not a number")
		}
		return nil
	}
	if len(raw) == 0 {
		raw = json.RawMessage("null")
	}
	return json.Unmarshal(raw, target)
}

// rustAnythingEncode marks the floats JSON cannot carry.
func rustAnythingEncode(v any) any {
	var f float64
	switch x := v.(type) {
	case float64:
		f = x
	case float32:
		f = float64(x)
	default:
		return v
	}
	switch {
	case math.IsNaN(f):
		return map[string]string{"$num": "NaN"}
	case math.IsInf(f, 1):
		return map[string]string{"$num": "Infinity"}
	case math.IsInf(f, -1):
		return map[string]string{"$num": "-Infinity"}
	case f == 0 && math.Signbit(f):
		return map[string]string{"$num": "-0"}
	}
	return v
}

type rustAnythingAnswer struct {
	Ok    json.RawMessage `json:"ok"`
	Error *string         `json:"error"`
	Panic *string         `json:"panic"`
}

func rustAnythingCall(name string, args ...any) (json.RawMessage, error) {
	for i, a := range args {
		args[i] = rustAnythingEncode(a)
	}
	encoded, err := json.Marshal(args)
	if err != nil {
		panic(err)
	}
	cName := C.CString(name)
	defer C.free(unsafe.Pointer(cName))
	cArgs := C.CString(string(encoded))
	defer C.free(unsafe.Pointer(cArgs))
	answer := C.rust_anything_call(cName, cArgs)
	defer C.rust_anything_free(answer)
	var a rustAnythingAnswer
	if err := json.Unmarshal([]byte(C.GoString(answer)), &a); err != nil {
		panic(err)
	}
	if a.Panic != nil {
		panic(*a.Panic)
	}
	if a.Error != nil {
		return nil, errors.New(*a.Error)
	}
	return a.Ok, nil
}

func rustAnythingMust(err error) {
	if err != nil {
		panic(err)
	}
}

// Markdown is the Rust port of `func Markdown(in Input) string` (`report/report.go:67`).
func Markdown(raArg0 Input) string {
	raw, err := rustAnythingCall("Markdown", raArg0)
	rustAnythingMust(err)
	var r0 string
	rustAnythingMust(rustAnythingDecode(raw, &r0))
	return r0
}
